export type TextSpan = {
  /**
   * Pixels the span's glyphs and its own decorations sit above the baseline; negative
   * values sit below it. The line keeps its height, so shifted text can overlap the
   * lines around it.
   */
  readonly baseline_shift?: ExpressionValue<number>;
  /** Text color. */
  readonly color?: ExpressionValue<Paint>;
  /** Font family name. */
  readonly font_family?: ExpressionValue<string>;
  /**
   * OpenType features, merged over the node's: a feature set here wins and the others are
   * kept. Within a word, the first span's features apply to all of it.
   */
  readonly font_features?: FontFeatures;
  /**
   * Font size in pixels. Where spans of one family, weight and style meet, a ligature or
   * other cluster across the boundary takes the size of the span it starts in.
   */
  readonly font_size?: ExpressionValue<number>;
  /** Font style. */
  readonly font_style?: ExpressionValue<TextFontStyle>;
  /** Font weight. Variable fonts render any value in their weight range. */
  readonly font_weight?: ExpressionValue<number>;
  /**
   * Box behind the text. `null` turns off the node's highlight. Its fields take literals or
   * expressions, but the whole highlight cannot be an expression.
   */
  readonly highlight?: TextHighlight | null;
  /** Extra space after every glyph in pixels. Negative values tighten the text. */
  readonly letter_spacing?: ExpressionValue<number>;
  /**
   * Line through the text. `null` turns off the node's strikethrough. Its fields take
   * literals or expressions, but the whole line cannot be an expression.
   */
  readonly strikethrough?: TextLine | null;
  /**
   * Outline along the glyphs. `null` turns off the node's stroke. Its fields take literals or
   * expressions, but the whole stroke cannot be an expression.
   */
  readonly stroke?: TextStroke | null;
  /** Text of the span. Required. */
  readonly text: ExpressionValue<string>;
  /** Case applied to the span's text. */
  readonly text_transform?: ExpressionValue<TextTransform>;
  /**
   * Line under the text. `null` turns off the node's underline. Its fields take literals or
   * expressions, but the whole line cannot be an expression.
   */
  readonly underline?: TextLine | null;
};
export type TextStroke = {
  /**
   * Where the outline lies: behind the glyphs and outside their edge, or over them and
   * centred on it.
   */
  readonly align?: ExpressionValue<TextStrokeAlign>;
  /** Outline color. */
  readonly paint?: ExpressionValue<Paint>;
  /** Outline width in pixels. */
  readonly width?: ExpressionValue<number>;
};
export type TextStrokeAlign = "outside" | "center";
export type TextTransform = "none" | "uppercase" | "lowercase" | "capitalize";
/** Length and frame rate. `fps` defaults to 30 at the root, and a template's timeline takes the root's `fps`. */
export type Timeline = {
  readonly duration_frames: number;
  readonly fps?: number;
};
export type ToneMapping = "none" | "aces" | "agx";
export type TransformSampling = RasterSampling;
export type ZoomBlurEdge = EdgeMode;

export interface CompositionNodeBase<TKind extends NodeKind> {
  readonly id: number;
  readonly type: TKind;
}

/** Generates a background raster texture. */
export interface BackgroundNode extends CompositionNodeBase<"background"> {
  readonly params?: {
    /** Output height in pixels. Use 0 to match the composition height. */
    readonly height?: number;
    /** Background paint. */
    readonly paint?: ExpressionValue<Paint>;
    /** Enables 4×4 supersampling when evaluating paint at each pixel. */
    readonly paint_supersample?: ExpressionValue<boolean>;
    /** Output width in pixels. Use 0 to match the composition width. */
    readonly width?: number;
  };
}

/** Applies a separable Gaussian blur to a raster. */
export interface BlurNode extends CompositionNodeBase<"blur"> {
  readonly params?: {
    /** Blur radius in pixels. Fractional radii blend smoothly. Radii above about 588 look the same. */
    readonly radius?: ExpressionValue<number>;
  };
}

/** Combines two raster alpha masks with boolean operations. */
export interface BooleanNode extends CompositionNodeBase<"boolean"> {
  readonly params?: {
    /** Boolean operation used to combine the two input masks. */
    readonly operation?: ExpressionValue<BooleanOperation>;
    /** Alpha above this cutoff counts as opaque; 0 applies no cutoff and keeps antialiased edges. */
    readonly threshold?: ExpressionValue<number>;
  };
}

/**
 * The viewpoint `render_3d` draws from, looking down its -Z. The first camera in a scene wins;
 * without one, `render_3d` views from 5 units along +Z with a 40° field of view.
 */
export interface Camera3dNode extends CompositionNodeBase<"camera_3d"> {
  readonly params?: {
    /** Farthest distance drawn, in world units. */
    readonly far?: ExpressionValue<number>;
    /** Vertical field of view in degrees, with a perspective projection. */
    readonly fov?: ExpressionValue<number>;
    /** Aims the camera at `target`, ignoring its rotation. */
    readonly look_at?: ExpressionValue<boolean>;
    /** Nearest distance drawn, in world units. */
    readonly near?: ExpressionValue<number>;
    /** Height of the view in world units, with an orthographic projection. */
    readonly ortho_height?: ExpressionValue<number>;
    /** Position in world units along X, Y and Z, in the parent's space. */
    readonly position?: ExpressionValue<Vec3>;
    /** How the scene is projected onto the image. */
    readonly projection?: Projection3d;
    /**
     * Rotation in degrees about X, Y and Z, applied as yaw about Y, then pitch about the turned
     * X, then roll about the turned Z.
     */
    readonly rotation?: ExpressionValue<Vec3>;
    /** Point along X, Y and Z the camera aims at while `look_at` is on, in its parent's space. */
    readonly target?: ExpressionValue<Vec3>;
  };
}

/**
 * Builds each channel of a raster from a channel of `source`, a channel of `other`, the luma of
 * either, 0 or 1. The output covers the area of `source`, and `other` is read at the same canvas
 * pixels, as transparent outside its own area. Choosing an `other_*` value with nothing connected
 * to `other` is an error. Colour is taken unpremultiplied and the result is premultiplied by the
 * output alpha.
 * 
 * To set a raster's alpha from another raster's luma, connect it to `other` and set `alpha` to
 * `other_luma`. To use the green channel of a matte as alpha, connect the matte to `other` and set
 * `alpha` to `other_green`.
 */
export interface ChannelsNode extends CompositionNodeBase<"channels"> {
  readonly params?: {
    /** Where the output's alpha comes from. */
    readonly alpha?: ChannelSource;
    /** Where the output's blue comes from. */
    readonly blue?: ChannelSource;
    /** Where the output's green comes from. */
    readonly green?: ChannelSource;
    /** Where the output's red comes from. */
    readonly red?: ChannelSource;
  };
}

/**
 * Removes a green or blue screen from a raster, in linear light.
 * 
 * Each pixel's chromaticity, its colour divided by its brightness, is compared with the key
 * color's, so a screen keys evenly from its shadows to its highlights. Pixels within
 * `tolerance` of the key are removed, kept in full beyond `tolerance + softness`, and fade
 * between. Near-black pixels have no reliable hue and are always kept. Then `spill` pulls the
 * key's dominant channel down to the larger of the other two on the pixels that remain, which
 * takes the green or blue cast out of edges and reflections. The result keeps the source's
 * alpha times the matte. With `matte_only`, the output is white with that alpha instead, which
 * can feed `merge`'s mask or `channels`.
 * 
 * For example, `{ "key_color": [0, 177, 64, 255], "tolerance": 0.1, "softness": 0.1 }` on
 * footage shot against a green screen leaves the subject over transparency.
 */
export interface ChromaKeyNode extends CompositionNodeBase<"chroma_key"> {
  readonly params?: {
    /** The screen color. Must be a solid color; a gradient is an error. */
    readonly key_color?: ExpressionValue<Paint>;
    /** Outputs the matte as white over transparent instead of the keyed image. */
    readonly matte_only?: ExpressionValue<boolean>;
    /**
     * How much further out the edge is feathered, from fully removed to fully kept. 0 is a hard
     * edge at `tolerance`.
     */
    readonly softness?: ExpressionValue<number>;
    /**
     * How much of the key color's cast is removed from the colors that are kept, from 0 for none
     * to 1 for all of it.
     */
    readonly spill?: ExpressionValue<number>;
    /**
     * How far a color may be from the key color in chromaticity, 0 for the same hue to 1.4 for
     * the furthest, and still be fully removed.
     */
    readonly tolerance?: ExpressionValue<number>;
  };
}

/** Plays a composition template, or its source, over a window of time. */
export interface ClipNode extends CompositionNodeBase<"clip"> {
  readonly params?: {
    /** Template from `compositions` to play; empty plays the `source` input instead. */
    readonly composition?: string;
    /**
     * Frames the clip plays for; -1 plays the template to its end, or a source to the end of
     * this composition.
     */
    readonly duration?: ExpressionValue<number>;
    /** What the clip shows after its window: nothing, its last frame, or the window again. */
    readonly end?: ClipEnd;
    /** Frames of the content skipped at the start, in the content's frames. */
    readonly offset?: ExpressionValue<number>;
    /** Values for the template's props by name; expressions run in this composition's time. */
    readonly props?: ClipProps;
    /** Playback rate of the content; must be greater than 0. */
    readonly speed?: ExpressionValue<number>;
    /** Frame the clip starts at, in this composition's frames. */
    readonly start?: ExpressionValue<number>;
  };
}

/**
 * Corrects the colour of a raster. Each step works on the straight colour in linear light, in
 * this order, and the alpha is untouched, so the defaults leave the raster unchanged.
 * 
 * 1. White balance multiplies red, green and blue by `2^(temperature / 2)`, `2^(-tint / 2)` and
 * `2^(-temperature / 2)`, divided by the Rec. 709 luminance of those three, so a neutral grey
 * keeps its brightness.
 * 
 * 2. Lift, gain and offset: `gain * (x + lift * (1 - x)) + offset` on each channel.
 * 
 * 3. Gamma: `max(x, 0) ^ (1 / gamma)` on each channel.
 * 
 * 4. Contrast: `pivot * (max(x, 0) / pivot) ^ contrast` on each channel.
 * 
 * 5. Curves act on the sRGB-encoded colour, clamped to 0..1: `master` on every channel, then
 * `red`, `green` and `blue` on theirs. Each is a smooth monotone curve through its points, flat
 * before the first and after the last. With no curves set, values above 1 pass through.
 * 
 * Each channel param is `[red, green, blue]`; an expression for one is a `vec3`. A curve is up
 * to 16 `[x, y]` points of numbers or expressions, with `x` increasing, all in 0..1:
 * `"curves": { "master": [[0, 0], [0.5, 0.65], [1, 1]] }` brightens the midtones.
 */
export interface ColorCorrectNode extends CompositionNodeBase<"color_correct"> {
  readonly params?: {
    /** Contrast around the pivot, in linear light: above 1 pushes values away from it. */
    readonly contrast?: ExpressionValue<number>;
    /** Tone curves on the sRGB-encoded colour, applied last. */
    readonly curves?: ColorCurves;
    /** Multiplier of each channel's linear light. */
    readonly gain?: ExpressionValue<Vec3>;
    /** Midtone gamma of each channel: above 1 brightens the midtones. Each is at least 0.01. */
    readonly gamma?: ExpressionValue<Vec3>;
    /** Raises the darks of each channel by this much, leaving white where it is. */
    readonly lift?: ExpressionValue<Vec3>;
    /** Linear light added to each channel after the gain. */
    readonly offset?: ExpressionValue<Vec3>;
    /** Linear light the contrast leaves unchanged, 0.18 for mid grey. */
    readonly pivot?: ExpressionValue<number>;
    /**
     * Colour temperature. Positive warms, scaling red up and blue down by half a stop at 1;
     * negative cools.
     */
    readonly temperature?: ExpressionValue<number>;
    /**
     * Green–magenta tint. Positive shifts toward magenta, scaling green down by half a stop at
     * 1; negative shifts toward green.
     */
    readonly tint?: ExpressionValue<number>;
  };
}

/** Applies a LUT-driven color transform to a raster, looking up its sRGB-encoded colour. */
export interface ColorGradeNode extends CompositionNodeBase<"color_grade"> {
  readonly params?: {
    /** Sampling filter used when reading LUT data. */
    readonly interpolation?: ExpressionValue<RasterSampling>;
    /**
     * An inline 1D LUT: `rgb1d:` and RGB stops separated by `;`, each three numbers from 0 to 1,
     * such as `rgb1d:0,0,0;0.2,0.1,0.3;1,1,1`; or `identity`. A value outside 0..1 is an error:
     * divide 0..255 values by 255. Set either this or `lut_source`.
     */
    readonly lut?: ExpressionValue<string>;
    /**
     * A 3D `.cube` LUT file (Adobe/Resolve) to grade with: a path or `media` alias, or
     * `asset:<id>` for an asset of the host's. Tables up to 129 points per axis and 64 MiB are
     * read, sampled with trilinear interpolation (`interpolation` `nearest` takes the nearest
     * point), and `DOMAIN_MIN`/`DOMAIN_MAX` set the input range they cover. 1D `.cube` tables are
     * not supported. Empty uses `lut`; setting both is an error.
     */
    readonly lut_source?: ExpressionValue<string>;
    /** Blend amount for the LUT transform. */
    readonly strength?: ExpressionValue<number>;
  };
}

/** Keeps a raster region in place and clears everything outside it. */
export interface CropNode extends CompositionNodeBase<"crop"> {
  readonly params?: {
    /** Height of the crop region in pixels. */
    readonly height?: ExpressionValue<number>;
    /** Width of the crop region in pixels. */
    readonly width?: ExpressionValue<number>;
    /** Left edge of the crop region in pixels. */
    readonly x?: ExpressionValue<number>;
    /** Top edge of the crop region in pixels. */
    readonly y?: ExpressionValue<number>;
  };
}

/** Blurs a raster along a line, as a straight motion blur. */
export interface DirectionalBlurNode extends CompositionNodeBase<"directional_blur"> {
  readonly params?: {
    /** Direction of the blur in degrees, clockwise from horizontal. */
    readonly angle?: ExpressionValue<number>;
    /** Length in pixels of the line each pixel is spread along, centred on it. */
    readonly distance?: ExpressionValue<number>;
    /** What the source reads as beyond the canvas. */
    readonly edge?: ExpressionValue<EdgeMode>;
  };
}

/**
 * Moves each pixel of `source` by the `map` pixel over it, in canvas pixels. A channel byte is
 * the sRGB code of the map's colour, and its move is scaled by the map's alpha, so transparent
 * areas of the map, and everything outside it, leave the source in place.
 */
export interface DisplacementMapNode extends CompositionNodeBase<"displacement_map"> {
  readonly params?: {
    /**
     * Pixels the source moves horizontally at full strength: a channel byte of 0 moves it this
     * far left, 255 nearly as far right, and 128 leaves it in place. Negative amounts reverse it.
     */
    readonly amount_x?: ExpressionValue<number>;
    /**
     * Pixels the source moves vertically at full strength: a channel byte of 0 moves it this far
     * up, 255 nearly as far down, and 128 leaves it in place. Negative amounts reverse it.
     */
    readonly amount_y?: ExpressionValue<number>;
    /** Map channel that drives horizontal displacement. */
    readonly channel_x?: ExpressionValue<DisplacementChannel>;
    /** Map channel that drives vertical displacement. */
    readonly channel_y?: ExpressionValue<DisplacementChannel>;
    /** What the source reads as beyond its edges. */
    readonly edge?: ExpressionValue<EdgeMode>;
    /** Sampling filter used to read the displaced source. */
    readonly sampling?: ExpressionValue<RasterSampling>;
  };
}

/** Adjusts raster exposure, contrast, and offset. */
export interface ExposureNode extends CompositionNodeBase<"exposure"> {
  readonly params?: {
    /** Contrast multiplier around sRGB-encoded mid grey, after the exposure. */
    readonly contrast?: ExpressionValue<number>;
    /** Exposure in stops, multiplying linear light by 2 to the power of this. */
    readonly exposure?: ExpressionValue<number>;
    /** Offset added to the sRGB-encoded colour, after the exposure and before the contrast. */
    readonly offset?: ExpressionValue<number>;
  };
}

/**
 * A 2D outline, a `path_2d`, `shape_2d` or `text_2d` wired into `geometry`, extruded into a solid:
 * a front cap facing +Z, a back cap facing -Z and side walls, lit, single-sided and white unless a
 * `material_3d` is wired into `material`. A `material_3d` wired into `side_material` covers the
 * side walls and the bevel instead, leaving the caps to `material`. The geometry's pixel coordinates, after its own
 * position, scale, rotation and anchor, become world X and Y at `units_per_pixel` units each, with
 * Y flipped, since 2D Y points down and 3D Y up. Pixel (0, 0) is the origin that `placement`
 * moves and turns the solid about, and nothing re-centres the solid on it: the geometry's
 * `position` and `anchor` decide where it sits about that origin, so a `shape_2d` at `position`
 * (0, 0) lies to the right of and below it on screen, and 100 pixels across it is 1 unit wide.
 * The extrusion is centred on Z = 0. The outline is filled by the nonzero rule, as a `text_3d`
 * glyph is, so holes of a path stay open whichever way they wind and overlapping subpaths join;
 * open subpaths are closed by a straight segment. Curves are flattened to within 0.001 world
 * units, so a larger or smaller `units_per_pixel` keeps them as smooth. An ellipse has as many
 * sides as that takes, at least 16 and at most 256, and each corner of a rounded rectangle a
 * quarter of as many for its own radius, at least 4 and at most 64. The flattening of a path or
 * a text coarsens where it would pass 16384 points. A solid takes at most 256 contours, 16384 points,
 * 262144 vertices and 786432 indices, and bevels fit outlines of at most 4096 points; more is a
 * render error. An `offset_2d` in the geometry is not supported yet and fails the render. The
 * mesh is built again only when the outline, `units_per_pixel` or the bevel change, or the
 * `depth` of a bevelled one, so animating the placement, the material or a plain extrusion's
 * depth costs no more than for a `shape_3d`.
 */
export interface Extrude3dNode extends CompositionNodeBase<"extrude_3d"> {
  readonly params?: {
    /**
     * Steps of the bevel's quarter-round profile, up to 16: 1 is a flat 45° chamfer, and 0 is no
     * bevel.
     */
    readonly bevel_segments?: ExpressionValue<number>;
    /**
     * How far the bevel rounds off the outline's edges in world units, in from the outline and in
     * from the front and back, up to half of `depth`; 0 is none. The outline keeps its size
     * where the sides meet the bevel. Where the outline is too thin or too tightly curved for
     * the bevel it gets the widest one that fits.
     */
    readonly bevel_size?: ExpressionValue<number>;
    /**
     * Thickness along Z in world units, centred on Z = 0 before `placement`, so the front faces
     * +Z at half of it. 0 is flat.
     */
    readonly depth?: ExpressionValue<number>;
    /** Position in world units along X, Y and Z, in the parent's space. */
    readonly position?: ExpressionValue<Vec3>;
    /**
     * Rotation in degrees about X, Y and Z, applied as yaw about Y, then pitch about the turned
     * X, then roll about the turned Z.
     */
    readonly rotation?: ExpressionValue<Vec3>;
    /** Scale multiplier along X, Y and Z, applied before the rotation. */
    readonly scale?: ExpressionValue<Vec3>;
    /**
     * World units that one pixel of the geometry spans, so that at the default of 0.01 a
     * 100 pixel outline is 1 unit across. The geometry's own position, scale and rotation apply
     * before it. 0 draws nothing. At most 1000000.
     */
    readonly units_per_pixel?: ExpressionValue<number>;
  };
}

/** Fills its geometry's outline with a paint, as a drawing of one drawable. */
export interface Fill2dNode extends CompositionNodeBase<"fill_2d"> {
  readonly params?: {
    /** Antialiases the fill's edge from its distance. Off, every pixel is covered or not. */
    readonly edge_antialias?: ExpressionValue<boolean>;
    /**
     * Width in the geometry's untransformed pixels over which the fill's edge fades out,
     * centred on the edge.
     */
    readonly feather?: ExpressionValue<number>;
    /** Opacity multiplier. */
    readonly opacity?: ExpressionValue<number>;
    /**
     * Fill paint. Accepts a solid color or gradient, laid out in the geometry's untransformed
     * pixels.
     */
    readonly paint?: ExpressionValue<Paint>;
  };
}

/**
 * Adds film grain to a raster: noise that follows the picture's brightness, in a pattern fixed to
 * the canvas, so it stays put as the source moves and looks the same at any render scale. Alpha
 * is untouched. Set `seed` to `"=frame"` for grain that changes every frame, as in
 * `{ "amount": 0.1, "size": 2, "seed": "=frame" }`.
 */
export interface FilmGrainNode extends CompositionNodeBase<"film_grain"> {
  readonly params?: {
    /**
     * Grain strength: the standard deviation of the grain in sRGB-encoded units, at the
     * brightness where `response` makes it strongest.
     */
    readonly amount?: ExpressionValue<number>;
    /** Uses one grain for all channels, which adds no colour noise, rather than one per channel. */
    readonly monochrome?: ExpressionValue<boolean>;
    /**
     * How much the strength follows the brightness. 0 grains every brightness alike, and 1
     * grains midtones only, leaving black and white clean.
     */
    readonly response?: ExpressionValue<number>;
    /**
     * Mixes in a coarser grain four times the size, for a paper-like tooth, without changing the
     * strength. 0 is fine grain only and 1 coarse grain only.
     */
    readonly roughness?: ExpressionValue<number>;
    /** Picks an unrelated pattern. Use an expression such as `=frame` to animate the grain. */
    readonly seed?: ExpressionValue<number>;
    /** Size of one grain in composition pixels. */
    readonly size?: ExpressionValue<number>;
  };
}

/** Generates opaque grey fractal noise, the same for a given seed and evolution. */
export interface FractalNoiseNode extends CompositionNodeBase<"fractal_noise"> {
  readonly params?: {
    /** Added to every pixel after contrast. */
    readonly brightness?: ExpressionValue<number>;
    /** Contrast multiplier around mid grey. */
    readonly contrast?: ExpressionValue<number>;
    /**
     * Morphs the pattern smoothly, in turns: it repeats every whole turn, so `=time` loops once a
     * second.
     */
    readonly evolution?: ExpressionValue<number>;
    /** Output height in pixels. Use 0 to match the composition height. */
    readonly height?: number;
    /** How the layers are summed. */
    readonly mode?: ExpressionValue<NoiseMode>;
    /** Layers of detail, from 1 to 8. Each adds features half the size, at half the strength. */
    readonly octaves?: ExpressionValue<number>;
    /** Moves the pattern right by this many pixels. */
    readonly offset_x?: ExpressionValue<number>;
    /** Moves the pattern down by this many pixels. */
    readonly offset_y?: ExpressionValue<number>;
    /** Size of the largest features in pixels. */
    readonly scale?: ExpressionValue<number>;
    /** Picks an unrelated pattern. */
    readonly seed?: ExpressionValue<number>;
    /** Output width in pixels. Use 0 to match the composition width. */
    readonly width?: number;
  };
}

/**
 * Adds a blurred copy of a raster's brightest pixels to it, as light: the glow's alpha is its
 * brightest channel, so dark pixels add nothing.
 */
export interface GlowNode extends CompositionNodeBase<"glow"> {
  readonly params?: {
    /** What the source reads as beyond the canvas. */
    readonly edge?: ExpressionValue<EdgeMode>;
    /** Outputs only the glow instead of adding it to the source. */
    readonly glow_only?: ExpressionValue<boolean>;
    /** Multiplies the glow's brightness, up to 1000. */
    readonly intensity?: ExpressionValue<number>;
    /** Glow blur radius in pixels, as on `blur`. Radii above about 588 look the same. */
    readonly radius?: ExpressionValue<number>;
    /**
     * Luminance from 0 to 1 where the glow starts, on the sRGB-encoded scale, so 0.5 is half way
     * up from black to white as they look. Brighter pixels glow more, white at full strength,
     * and 1 lets nothing glow. Past 254/255 white dims too, so the glow fades out
     * continuously as the threshold reaches 1.
     */
    readonly threshold?: ExpressionValue<number>;
    /**
     * Glow colour when `tint_enabled` is set, at the brightness of the light that casts it. Must
     * be a solid color; a gradient is an error.
     */
    readonly tint?: ExpressionValue<Paint>;
    /** Colours the glow with `tint` instead of the colours that cast it. */
    readonly tint_enabled?: ExpressionValue<boolean>;
  };
}

/**
 * Redraws a raster as a grid of dots or lines in `ink` on `paper`, as in a print screen. Each
 * cell takes the darkness, 1 minus the luma of the sRGB-encoded colour, at its centre, and
 * covers that fraction of its area, so a flat colour gives uniform dots and black fills the
 * whole cell. The grid is anchored to the canvas origin, so the pattern stays put when the
 * source moves, and the source's alpha is kept.
 * 
 * For example, `{ "pitch": 55, "angle": -19, "ink": [110, 28, 38, 255], "paper": [120, 134, 150, 255] }`
 * over a flat colour gives oxblood dots on a grey-blue ground, on a grid rotated -19 degrees.
 */
export interface HalftoneNode extends CompositionNodeBase<"halftone"> {
  readonly params?: {
    /** Rotation of the grid in degrees. */
    readonly angle?: ExpressionValue<number>;
    /** Color where the source is dark. Must be a solid color; a gradient is an error. */
    readonly ink?: ExpressionValue<Paint>;
    /** Color where the source is light. Must be a solid color; a gradient is an error. */
    readonly paper?: ExpressionValue<Paint>;
    /** Width and height of a cell in pixels. */
    readonly pitch?: ExpressionValue<number>;
    /** What each cell draws. */
    readonly shape?: ExpressionValue<HalftoneShape>;
  };
}

/** Adjusts raster hue, saturation, and lightness of the sRGB-encoded colour. */
export interface HueSaturationNode extends CompositionNodeBase<"hue_saturation"> {
  readonly params?: {
    /** Hue rotation in degrees. */
    readonly hue_degrees?: ExpressionValue<number>;
    /** Lightness offset. */
    readonly lightness?: ExpressionValue<number>;
    /** Saturation multiplier. */
    readonly saturation?: ExpressionValue<number>;
  };
}

/**
 * Shows a raster, such as text or video, on a flat rectangle facing +Z. With no `material_3d`
 * wired into `material` it is unlit and double-sided, so it looks as it does in 2D while it faces
 * the camera. A `material_3d` applies exactly as it is set, so a default one makes the plane lit
 * and single-sided; set its `unlit` and `double_sided` to keep the plane as it looks unwired.
 * A plane is drawn blended, ordered by its centre among blended objects, so its transparent parts
 * show what is behind it. Planes that intersect, or overlap while crossing in depth, can show in
 * the wrong order; layers separated in depth, and opaque shapes in front of or behind planes, are
 * ordered correctly. `opaque` draws a plane that has no transparent pixels with the opaque
 * objects instead. A source keeps its detail when it is shown at its own size or larger; shown
 * smaller, it is filtered with mipmaps, trilinearly and anisotropically, before `render_3d`'s
 * `supersample` averages it, unless `sampling` is `nearest`.
 */
export interface ImagePlane3dNode extends CompositionNodeBase<"image_plane_3d"> {
  readonly params?: {
    /**
     * Draws the plane with the opaque objects, writing depth, rather than blended. For a source
     * with no transparent pixels, this orders the plane correctly against any geometry it
     * intersects or crosses in depth. Alpha is then ignored: the colour's alpha, `opacity` and the
     * source's alpha. A source pixel that is transparent shows its colour at full opacity, which
     * is black for a fully transparent one, and a half-transparent one shows its colour
     * undimmed. It casts a shadow over its whole rectangle. A shadow catcher is always drawn as
     * one, so this has no effect on it.
     */
    readonly opaque?: ExpressionValue<boolean>;
    /** Position in world units along X, Y and Z, in the parent's space. */
    readonly position?: ExpressionValue<Vec3>;
    /**
     * Shows only this part of the source, `[x, y, width, height]` in the source's pixels from its
     * top left, on a plane that covers just that part, so a plane showing a region is where it
     * would be and as big as it would be with the whole source on it: it looks as a plane
     * showing a `crop` of that region does, where `width` is still the width of the whole
     * source, and `position`, `rotation` and `scale` pivot about the whole source's centre.
     * Cut off at the source's edges as `crop` cuts its region, and a region with no pixel
     * left shows nothing. Each of the four numbers takes an integer or an expression, which is
     * truncated toward zero as `crop`'s are; the whole region cannot be an expression. Unset
     * shows the whole source. Planes showing parts of one source share its texture and mip
     * levels and draw together, so a region costs nothing beyond the plane, where a `crop`
     * costs a raster the size of the source and a draw of its own. Sampling is kept inside the
     * region, so what is outside it isn't meant to show. To keep it so under strong minification,
     * the band along each edge of the region that is inside the source, and all of a narrow
     * region, is sampled from a sharper mip level than its footprint, since a texel of a shared
     * level can hold pixels from both sides of the edge: it can alias or shimmer there where a
     * `crop` would be smooth, across the whole of a piece drawn much smaller than its pixels.
     */
    readonly region?: Region;
    /**
     * Rotation in degrees about X, Y and Z, applied as yaw about Y, then pitch about the turned
     * X, then roll about the turned Z.
     */
    readonly rotation?: ExpressionValue<Vec3>;
    /**
     * `nearest` gives each pixel the one source texel under it at any size, for pixel art:
     * magnified, texels stay hard-edged squares; shown smaller, a pixel picks one texel instead
     * of averaging the ones it covers, so it aliases and shimmers where `linear` is smooth.
     * `render_3d`'s `supersample` still averages its samples within each pixel.
     */
    readonly sampling?: ExpressionValue<RasterSampling>;
    /** Scale multiplier along X, Y and Z, applied before the rotation. */
    readonly scale?: ExpressionValue<Vec3>;
    /**
     * Width in world units, 1 being as wide as a default `shape_3d` box; the height follows the
     * aspect ratio of the source's full display size.
     */
    readonly width?: ExpressionValue<number>;
  };
}

/**
 * Draws its input scene `count` times, each copy placed by `position`, `rotation` and `scale`
 * evaluated for that copy, where `instance` is the copy's index from 0 and `instance_count` is
 * `count`: `position = vec3((instance % 10) * 1.5, 0, floor(instance / 10) * 1.5)` lays out a
 * grid, and a ring, a spiral or a path follow from `sin`, `cos` and `path_point` of
 * `instance / instance_count`. A copy is placed in the input scene's own space, so it turns and
 * scales about the origin of the scene's own coordinates.
 * 
 * `tint` colours each copy: `tint = rgb(255 * instance / instance_count, 128, 255)` shifts the
 * colour along the copies, and it multiplies the objects' base colours and emissive light, so
 * copies of a white or textured object take the tint's colour. Its alpha is ignored.
 * 
 * Copies placed by hand are listed in `copies` instead, as literals: `copies = [{ "position":
 * [0, 0, 0], "scale": [1, 2, 1], "tint": "#ff8040" }, { "position": [2, 0, 1], "rotation":
 * [0, 45, 0] }]` places two. `count`, `position`, `rotation`, `scale` and `tint` must not be set
 * beside a `copies` list that has copies, or `check` fails. A list is placed once, so a frame
 * after the first does no work per copy.
 * 
 * Copies share the input's meshes, textures, materials and joint matrices on the GPU, so every
 * copy of a skinned model plays the same animation at the same time. Opaque surfaces draw all
 * their copies at once from placements and tints kept on the GPU, so a moving camera or parent
 * costs nothing per copy, and neither does a frame when the params don't read the frame. Blended
 * surfaces, and those showing a raster, are copied one by one, which costs more. Only the objects
 * are copied: the input's lights and camera appear once, placed as they would be without the node,
 * so copies don't multiply a scene's lighting. Shadows, fog and the environment treat a copy as any
 * other object. An `instance_3d` may hold another, which multiplies their counts, up to 8 deep.
 * A scene draws at most 100000 objects in all, counting each copy's objects, and a count that
 * would exceed this fails the render. The node is static when its params don't read the frame
 * and its scene is static.
 */
export interface Instance3dNode extends CompositionNodeBase<"instance_3d"> {
  readonly params?: {
    /**
     * Copies to place, each given literally as `{ position, rotation, scale, tint }` with any
     * field left out taking the default of the param of that name: position and rotation 0,
     * scale 1 and a white tint. The list can't hold expressions and holds at most 100000
     * copies. An empty list places none of its own. When it has copies, `count`, `position`,
     * `rotation`, `scale` and `tint` must not be set, and `check` fails if they are.
     */
    readonly copies?: InstanceCopies;
    /**
     * Copies to place, from 0 to 100000. 0 leaves the node's scene out entirely, lights and
     * cameras too. Not set together with `copies`.
     */
    readonly count?: ExpressionValue<number>;
    /** Position in world units along X, Y and Z of each copy, in the scene's own space. Evaluated for every copy, and can read `instance` and `instance_count`. */
    readonly position?: ExpressionValue<Vec3>;
    /** Rotation in degrees about X, Y and Z of each copy, applied as yaw about Y, then pitch about the turned X, then roll about the turned Z. Evaluated for every copy, and can read `instance` and `instance_count`. */
    readonly rotation?: ExpressionValue<Vec3>;
    /** Scale multiplier along X, Y and Z of each copy, applied before the rotation. Evaluated for every copy, and can read `instance` and `instance_count`. */
    readonly scale?: ExpressionValue<Vec3>;
    /**
     * Colour that multiplies the base colour of every object in each copy, texture and base
     * colour map included, and the light they give off, so a glowing copy glows in its tint.
     * White leaves a copy as it is. Evaluated for every copy, and can read `instance` and
     * `instance_count`. Its alpha is ignored: a copy is opaque or blended exactly as its
     * material makes it. Tints of nested `instance_3d` nodes multiply. Must be a solid color; a
     * gradient fails `check`.
     */
    readonly tint?: ExpressionValue<Color>;
  };
}

/**
 * A 2D profile, a `path_2d`, `shape_2d` or `text_2d` wired into `geometry`, spun around the world Y axis
 * into a solid of revolution, lit, single-sided and white unless a `material_3d` is wired into
 * `material`. The geometry's pixel coordinates, after its own position, scale, rotation and
 * anchor, become world units at `units_per_pixel` each: a point's X is its distance from the axis
 * and its Y, flipped since 2D Y points down and 3D Y up, its height, so pixel (0, 0) is on the
 * axis at height 0, which is the origin that `placement` moves and turns the solid about. Points
 * left of the axis are put on it. Each contour becomes a strip of quads around the axis, shaded
 * smoothly around it, and along the profile except at corners sharper than 30°, which stay hard.
 * A closed contour makes a closed ring solid whose faces point out of the area it encloses,
 * whichever way it winds. An open contour makes a surface whose front faces the right-hand side of
 * the direction it is drawn in, and which is seen from both sides only if its material is
 * `double_sided`. A point on the axis is a pole, where the surface closes to a point, such as the
 * tip of a cone or the top of a dome; the quads there are triangles, so no triangle without
 * area is left in the mesh, and a closed contour's edge along the axis draws nothing. Contours
 * are spun separately, so one inside another is a separate solid and not a hole. A solid takes
 * at most 256 contours, 16384 profile points, 262144 vertices and 786432 indices in all, which
 * is the profile's vertices times the steps around; more is a render error. The mesh is built
 * again only when the profile, `units_per_pixel`, `segments` or `sweep` change, so animating the
 * placement or the material costs no more than for a `shape_3d`.
 */
export interface Lathe3dNode extends CompositionNodeBase<"lathe_3d"> {
  readonly params?: {
    /** Position in world units along X, Y and Z, in the parent's space. */
    readonly position?: ExpressionValue<Vec3>;
    /**
     * Rotation in degrees about X, Y and Z, applied as yaw about Y, then pitch about the turned
     * X, then roll about the turned Z.
     */
    readonly rotation?: ExpressionValue<Vec3>;
    /** Scale multiplier along X, Y and Z, applied before the rotation. */
    readonly scale?: ExpressionValue<Vec3>;
    /**
     * Steps around the axis for a whole turn, from 3 to 512; a `sweep` of less than 360° has
     * proportionally fewer. The surface is shaded smoothly around the axis, so a few dozen look
     * round.
     */
    readonly segments?: ExpressionValue<number>;
    /**
     * How far around the axis the profile turns, in degrees, from 0 to 360, starting on +X and
     * turning towards -Z. Under 360 leaves an open wedge with no end caps; 0 draws nothing.
     */
    readonly sweep?: ExpressionValue<number>;
    /**
     * World units that one pixel of the geometry spans, so that at the default of 0.01 a
     * 100 pixel profile is 1 unit across. The geometry's own position, scale and rotation apply
     * before it. 0 draws nothing. At most 1000000.
     */
    readonly units_per_pixel?: ExpressionValue<number>;
  };
}

/**
 * Bends a raster the way a lens does. With `direction: "distort"`, a pixel at `p` from the optical
 * centre reads the source at `p * (1 + k1 r² + k2 r⁴)`, where `r` is its distance in
 * half-diagonals, so positive `k1` gives barrel distortion and negative `k1` pincushion. With
 * `direction: "undistort"` it reads where that lens would have put it, undoing a distortion with
 * the same coefficients. The result covers the source's frame, and looks the same at any render
 * scale.
 * 
 * To match graphics to footage, set the footage's coefficients and `direction: "undistort"` on
 * the footage, or leave `direction` as `"distort"` on the graphics. For a finishing look, try
 * `k1: 0.15` with `chromatic_aberration: 0.004`.
 */
export interface LensDistortionNode extends CompositionNodeBase<"lens_distortion"> {
  readonly params?: {
    /** The optical centre as a fraction of the frame: `[0.5, 0.5]` is the middle. */
    readonly center?: ExpressionValue<Vec2>;
    /**
     * How far red and blue scale apart from green, as a fraction of each pixel's distance from
     * the optical centre. Positive values magnify red and shrink blue, so red fringes lie
     * outside blue ones and grow toward the corners.
     */
    readonly chromatic_aberration?: ExpressionValue<number>;
    /** Whether to apply the lens or remove it. */
    readonly direction?: ExpressionValue<LensDirection>;
    /** What the source reads as beyond its frame. */
    readonly edge?: ExpressionValue<EdgeMode>;
    /** Whether to scale the result so that no edge is exposed. */
    readonly fit?: ExpressionValue<LensFit>;
    /**
     * Radial distortion, the `r²` coefficient. Positive values bow straight lines outward
     * (barrel), negative values bow them inward (pincushion). Distances are measured from the
     * optical centre in units of the frame's half-diagonal, so the corners are at 1.
     */
    readonly k1?: ExpressionValue<number>;
    /** Radial distortion, the `r⁴` coefficient. It bends mostly toward the corners. */
    readonly k2?: ExpressionValue<number>;
  };
}

/** Remaps raster black, white, gamma, and output range of the sRGB-encoded colour. */
export interface LevelsNode extends CompositionNodeBase<"levels"> {
  readonly params?: {
    /** Input black point. */
    readonly black_point?: ExpressionValue<number>;
    /** Midtone gamma adjustment. */
    readonly gamma?: ExpressionValue<number>;
    /** Output black level. */
    readonly output_black?: ExpressionValue<number>;
    /** Output white level. */
    readonly output_white?: ExpressionValue<number>;
    /** Input white point. */
    readonly white_point?: ExpressionValue<number>;
  };
}

/** A light. A scene without any is lit by a default key light and ambient fill. */
export interface Light3dNode extends CompositionNodeBase<"light_3d"> {
  readonly params?: {
    /**
     * Casts shadows from objects that block it onto those behind them. A scene draws shadows for
     * its first 8 lights that cast them, in the order its scene inputs are wired, and warns
     * about the rest. A spot light's shadows reach 170° across at most.
     */
    readonly cast_shadows?: ExpressionValue<boolean>;
    /** Light colour. Must be a solid color; a gradient fails `check`. */
    readonly color?: ExpressionValue<Color>;
    /** Unitless brightness multiplier; point and spot lights fall off with the square of distance. */
    readonly intensity?: ExpressionValue<number>;
    /** Kind of light. */
    readonly light?: Light3dKind;
    /** Position in world units along X, Y and Z, in the parent's space. */
    readonly position?: ExpressionValue<Vec3>;
    /** Distance past which a point or spot light has no effect; 0 is unlimited. */
    readonly range?: ExpressionValue<number>;
    /**
     * Rotation in degrees about X, Y and Z, applied as yaw about Y, then pitch about the turned
     * X, then roll about the turned Z.
     */
    readonly rotation?: ExpressionValue<Vec3>;
    /**
     * How far from the camera, along its view, a directional light's shadows reach, fading out
     * over the last tenth. Its shadow map spreads over what the camera sees of the scene up to
     * here, so a larger distance trades sharpness for reach; a scene the camera sees nearer
     * keeps its full sharpness.
     */
    readonly shadow_distance?: ExpressionValue<number>;
    /**
     * Width in world units over which shadow edges blur, up to 16 texels of the light's shadow
     * map, which is up to 4096 texels across and shared among the shadow-casting lights.
     */
    readonly shadow_softness?: ExpressionValue<number>;
    /** Full angle of a spot light's cone in degrees. */
    readonly spot_angle?: ExpressionValue<number>;
    /** Fraction of a spot light's cone, from its edge, that fades out. */
    readonly spot_softness?: ExpressionValue<number>;
  };
}

/**
 * How a surface responds to light, for the 3D objects it is wired into through their `material`
 * input. One `material_3d` can be wired to any number of objects, which then share its params,
 * so changing it changes them all. Each param takes an expression as it does on any node.
 * Objects with no material wired in use a lit, single-sided white one; an `image_plane_3d` uses
 * an unlit, double-sided one. A raster wired into `texture` shows on a `shape_3d`, multiplied by
 * `color`, through the texture coordinates `shape_3d` describes, lit and shadowed like the rest
 * of the surface, and filtered as an image plane's source is unless `sampling` is `nearest`.
 * Its alpha counts where the material blends or masks, through `opacity` or the colour's alpha.
 * Wired into any other object, a material with a texture fails the render.
 * 
 * `alpha_mode` `mask` draws a cut-out card, such as a `text` raster on an `image_plane_3d` whose
 * material is unlit and double-sided, with the opaque objects so it orders correctly where cards
 * cross. As a glTF `MASK` material does, it shows only the texels that reach `alpha_cutoff`.
 */
export interface Material3dNode extends CompositionNodeBase<"material_3d"> {
  readonly params?: {
    /** The alpha a texel needs to show when `alpha_mode` is `mask`. Not read otherwise. */
    readonly alpha_cutoff?: ExpressionValue<number>;
    /**
     * `blend` draws the surface blended where its alpha is below 1. `mask` draws it with the
     * opaque objects, so it writes depth and crossing masked surfaces order correctly: texels
     * whose alpha, the colour's times `opacity` times the texture's or raster's, is below
     * `alpha_cutoff` are discarded and the rest show at full opacity. Masked surfaces cast
     * shadows shaped by the cut-out. It takes precedence over `opaque` on an `image_plane_3d`,
     * and with `shadow_catcher` fails `check`.
     */
    readonly alpha_mode?: MaterialAlphaMode;
    /**
     * Blocks light from lights that cast shadows. A blended surface blocks it where its alpha is
     * at least half. Unlit and glowing surfaces block it too, so a shape standing in for a light,
     * such as a bulb around a point light, needs this off.
     */
    readonly cast_shadows?: ExpressionValue<boolean>;
    /**
     * Base colour, which multiplies the `texture` on a shape and the raster on an image plane.
     * Must be a solid color; a gradient fails `check`.
     */
    readonly color?: ExpressionValue<Color>;
    /** Draws the back of each face too. */
    readonly double_sided?: ExpressionValue<boolean>;
    /** Light the surface gives off on its own, as a multiple of its base colour. */
    readonly emissive?: ExpressionValue<number>;
    /** 0 is a dielectric such as plastic, 1 a bare metal. */
    readonly metallic?: ExpressionValue<number>;
    /**
     * Opacity multiplier. With `alpha_mode` `blend`, anything below 1 is drawn blended, after
     * opaque objects.
     */
    readonly opacity?: ExpressionValue<number>;
    /** Darkens where shadows fall on it. An unlit surface shows them as `unlit_shadows` says. */
    readonly receive_shadows?: ExpressionValue<boolean>;
    /** 0 is a mirror finish, 1 fully diffuse. */
    readonly roughness?: ExpressionValue<number>;
    /**
     * How a shape reads its `texture`, as `sampling` on `image_plane_3d`: `nearest` gives each
     * pixel the one texel under it at any size, for pixel art.
     */
    readonly sampling?: ExpressionValue<RasterSampling>;
    /**
     * Shows nothing but the shadows falling on it, as transparent black that darkens what the
     * render is composited over by as much light as the shadows take away, times the colour's
     * alpha, the opacity and, on an image plane, its raster's alpha, whatever `unlit` says. It
     * shows none of its colours, hides what is behind it wherever that alpha isn't 0, and casts
     * no shadows, so a ground plane catching a model's shadow can stand in for the floor of 2D
     * footage behind it.
     */
    readonly shadow_catcher?: ExpressionValue<boolean>;
    /** Shows the base colour as is, ignoring lights. */
    readonly unlit?: ExpressionValue<boolean>;
    /**
     * How much an unlit surface darkens where shadows fall on it, from 0, which shows none, to
     * 1, where a fully shadowed point is black. Lit surfaces ignore it, as do surfaces that
     * don't receive shadows.
     */
    readonly unlit_shadows?: ExpressionValue<number>;
  };
}

/** Binds an external image or video frame as a GPU texture. */
export interface MediaInNode extends CompositionNodeBase<"media_in"> {
  readonly params?: {
    /** Whether a video's colour is already multiplied by its alpha. Images ignore it. */
    readonly alpha?: ExpressionValue<AlphaMode>;
    /** Type of external media source. */
    readonly kind?: ExpressionValue<MediaInSourceKind>;
    /** Behavior when playback leaves the source range. */
    readonly loop_mode?: ExpressionValue<LoopMode>;
    /** First source frame past the range; the source's end when unset. */
    readonly range_end?: ExpressionValue<number>;
    /** First source frame to include. */
    readonly range_start?: ExpressionValue<number>;
    /** External media source: a path or `media` alias, or `asset:<id>` for an asset of the host's. */
    readonly source?: ExpressionValue<string>;
    /** Playback speed multiplier. */
    readonly speed?: ExpressionValue<number>;
  };
}

/**
 * Converts its source into the final composition output: sRGB-encoded and quantised once to the
 * output's format.
 */
export interface MediaOutputNode extends CompositionNodeBase<"media_output"> {
  readonly params?: Readonly<Record<string, never>>;
}

/** Composites an overlay raster over a base raster. */
export interface MergeNode extends CompositionNodeBase<"merge"> {
  readonly params?: {
    /**
     * Blend mode used when combining the overlay with the base raster. `normal` composites in
     * linear light; every other mode applies its formula to the sRGB-encoded colours and
     * composites the result in linear light.
     */
    readonly blend_mode?: ExpressionValue<BlendMode>;
    /** Softens the mask edge with a Gaussian blur of this radius in pixels, applied before `invert`. Radii above about 588 look the same. */
    readonly feather?: ExpressionValue<number>;
    /** Swaps the masked and unmasked areas. */
    readonly invert?: ExpressionValue<boolean>;
    /** Channel of the `mask` input that controls overlay visibility. */
    readonly mask_mode?: MaskMode;
    /** Overlay opacity applied before compositing. */
    readonly opacity?: ExpressionValue<number>;
  };
}

/**
 * Draws drawings one over another in input order, the first lowest, placing them together by
 * its transform. The transform applies to everything inside, strokes and shadows included.
 */
export interface Merge2dNode extends CompositionNodeBase<"merge_2d"> {
  readonly params?: {
    /** Pivot for scale and rotation, in pixels relative to `position`. */
    readonly anchor?: ExpressionValue<Vec2>;
    /** Origin in pixels. */
    readonly position?: ExpressionValue<Vec2>;
    /** Clockwise rotation in degrees, about the anchor. */
    readonly rotation?: ExpressionValue<number>;
    /** Scale multiplier per axis, about the anchor. */
    readonly scale?: ExpressionValue<Vec2>;
  };
}

/** Groups scenes into one, placed together by its transform. */
export interface Merge3dNode extends CompositionNodeBase<"merge_3d"> {
  readonly params?: {
    /** Position in world units along X, Y and Z, in the parent's space. */
    readonly position?: ExpressionValue<Vec3>;
    /**
     * Rotation in degrees about X, Y and Z, applied as yaw about Y, then pitch about the turned
     * X, then roll about the turned Z.
     */
    readonly rotation?: ExpressionValue<Vec3>;
    /** Scale multiplier along X, Y and Z, applied before the rotation. */
    readonly scale?: ExpressionValue<Vec3>;
  };
}

/**
 * A glTF model: the default scene of a `.glb`, with its metallic-roughness materials, vertex
 * colours, two sets of texture coordinates with `KHR_texture_transform`, skins, morph targets
 * and animation clips. A raster wired into `texture` shows on the surfaces of the material
 * `texture_material` names, such as a screen. The model's own lights and a camera are added with
 * `lights` and `camera`. Points, lines, and triangle strips and fans aren't drawn, with a
 * `scene.model_primitives_skipped` warning.
 */
export interface Model3dNode extends CompositionNodeBase<"model_3d"> {
  readonly params?: {
    /**
     * The animation clip to play, by its name or else its index; empty plays none. A model's
     * clips are listed in the `animations` of its upload's `metadata` on a host that takes
     * uploads, and by `modelInfo` in the browser bindings.
     */
    readonly animation?: ExpressionValue<string>;
    /** Plays the clip again from its start once it ends, rather than holding its last pose. */
    readonly animation_loop?: ExpressionValue<boolean>;
    /** Seconds into the clip at the clip's first frame. */
    readonly animation_offset?: ExpressionValue<number>;
    /** Playback speed multiplier. */
    readonly animation_speed?: ExpressionValue<number>;
    /**
     * The model's camera to view the scene from, by its name or else its index, placed by the
     * first node that places it, without that node's scale; empty uses none. It counts as a
     * `camera_3d` at this node, so the first camera in the scene still wins. Its aspect ratio is
     * the output's. A model's cameras are listed in the `cameras` of its upload's `metadata` on
     * a host that takes uploads, and by `modelInfo` in the browser bindings.
     */
    readonly camera?: ExpressionValue<string>;
    /**
     * Blocks light from lights that cast shadows, in the posed shape and where masked or blended
     * materials' alpha reaches their cutoff, or half for blended ones. Unlit and glowing
     * materials block it too, so a model of a lamp around a light needs this off.
     */
    readonly cast_shadows?: ExpressionValue<boolean>;
    /**
     * Adds the model's own `KHR_lights_punctual` lights to the scene, where its nodes place
     * them, as `light_3d` nodes there would light it: a directional light's intensity, in lux, and
     * a point or spot light's, in candela, are `light_3d` intensities as they are, so a point
     * light of intensity `I` lights a surface `d` metres away as a directional one of `I / d²`
     * does. A spot light's cone fades from its inner angle out to its outer one. They cast no
     * shadows, and a scene they light gets no default lights.
     */
    readonly lights?: ExpressionValue<boolean>;
    /** Position in world units along X, Y and Z, in the parent's space. */
    readonly position?: ExpressionValue<Vec3>;
    /** Darkens where shadows fall on its lit surfaces. */
    readonly receive_shadows?: ExpressionValue<boolean>;
    /**
     * Rotation in degrees about X, Y and Z, applied as yaw about Y, then pitch about the turned
     * X, then roll about the turned Z.
     */
    readonly rotation?: ExpressionValue<Vec3>;
    /** Scale multiplier along X, Y and Z, applied before the rotation. */
    readonly scale?: ExpressionValue<Vec3>;
    /**
     * A binary glTF (`.glb`) file with its buffers and images inside it: a path or `media`
     * alias, or `asset:<id>` for a model asset of the host's.
     */
    readonly source?: ExpressionValue<string>;
    /**
     * The material, by name, whose surfaces show the `texture` input instead, unlit. A model's
     * materials are listed in the `materials` of its upload's `metadata` on a host that takes
     * uploads, and by `modelInfo` in the browser bindings.
     */
    readonly texture_material?: ExpressionValue<string>;
  };
}

/**
 * Blurs everything that moves in its source, including what analytic motion blur can't see:
 * animated sizes, path data, motion upstream of a transform and motion inside video. Analytic
 * motion blur in the source is off while it samples, and so is a `motion_blur` inside it.
 * Content that already has its own motion blur, like a video recorded with it, is blurred
 * twice.
 */
export interface MotionBlurNode extends CompositionNodeBase<"motion_blur"> {
  readonly params?: {
    /**
     * Sub-frames rendered across the shutter, from 1 to 64. Each renders the whole source
     * again, so the cost grows with it. 1 renders the source once, at the frame.
     */
    readonly samples?: ExpressionValue<number>;
    /**
     * Shutter angle in degrees, centred on the frame, from 0 to 360. 0 is off, 180 is the
     * usual film look and 360 smears over the whole frame.
     */
    readonly shutter?: ExpressionValue<number>;
  };
}

/**
 * Grows its geometry's outline by `offset`, or shrinks it when negative, rounding the corners
 * it grows around; chained offsets add up. Fills and strokes of the result follow the offset
 * outline: a stroke is centred on it, so it lies where the signed distance from the original
 * outline equals the offset. The offset is taken from the outline the fill covers, so a path's
 * open contours count as closed by their closing segment, and a stroke of an offset path
 * strokes that closed outline. Trim and dash on such a stroke are measured along the original
 * outline and carried across to the offset one, so around a corner the offset rounds, the
 * stroke keeps the place the corner has.
 */
export interface Offset2dNode extends CompositionNodeBase<"offset_2d"> {
  readonly params?: {
    /**
     * Distance in the geometry's untransformed pixels that the outline grows outward by, or
     * shrinks inward by when negative.
     */
    readonly offset?: ExpressionValue<number>;
  };
}

/** Uniformly adjusts raster opacity. */
export interface OpacityNode extends CompositionNodeBase<"opacity"> {
  readonly params?: {
    /** Opacity multiplier applied to the raster. */
    readonly opacity?: ExpressionValue<number>;
  };
}

/**
 * Reduces a raster to a few levels with a Bayer threshold matrix, which trades the banding of
 * plain quantizing for a fixed, regular pattern. Values quantize in sRGB-encoded space. The
 * matrix is anchored to the canvas origin and each cell is a whole number of device pixels, so
 * cell edges are never antialiased. The source's alpha is kept.
 * 
 * For example, `{ "matrix": "bayer8", "pitch": 2, "ink": [20, 24, 40, 255], "paper": [240, 232, 210, 255] }`
 * redraws a photo in two colours with cells of 2 pixels.
 */
export interface OrderedDitherNode extends CompositionNodeBase<"ordered_dither"> {
  readonly params?: {
    /**
     * Color of the darkest level. Must be a solid color; a gradient is an error. Only
     * `ink_paper` uses it.
     */
    readonly ink?: ExpressionValue<Paint>;
    /** Levels each value quantizes to, at least 2. 2 gives only the extremes. */
    readonly levels?: ExpressionValue<number>;
    /** The threshold matrix. */
    readonly matrix?: ExpressionValue<DitherMatrix>;
    /** What the node draws. */
    readonly mode?: ExpressionValue<DitherMode>;
    /**
     * Color of the lightest level. Must be a solid color; a gradient is an error. Only
     * `ink_paper` uses it.
     */
    readonly paper?: ExpressionValue<Paint>;
    /**
     * Width and height of a matrix cell in pixels. A cell is a whole number of output pixels, at
     * least one, so the pitch rounds at render scales where it isn't.
     */
    readonly pitch?: ExpressionValue<number>;
  };
}

/**
 * Draws `count` copies of its `object` scene as particles, scattered over its `surface` scene:
 * each is emitted from a point picked at random over the surface's triangles, as likely
 * anywhere as anywhere else of the same area, then moves along a direction near the
 * triangle's normal with `speed` and falls with `gravity`. Without a surface, particles are
 * emitted from the node's origin along +Y. The surface isn't drawn; wire it into a `merge_3d` as
 * well to show it. The defaults scatter all the particles at once and keep them still, which
 * suits grass on a hill or rocks on a floor; a `rate`, `lifetime` and `speed` make it an emitter,
 * such as sparks or snow.
 * 
 * A frame's particles depend only on the seed, the params, the surface and the time, which is
 * the frame over the composition's frame rate, so any frame renders alone and the same, and a
 * `motion_blur` blurs particles by their motion. Particles are placed on the GPU: a frame's CPU
 * work doesn't grow with `count`, and each `particles_3d` counts once towards a scene's 100000
 * objects, however many particles it draws.
 * 
 * The surface is taken at rest: a skinned or morphed model emits from its vertices as they are
 * stored, unposed, and an `instance_3d` in it emits from all its copies. Each object of the
 * surface emits in proportion to its area in the world, so a flat plane or a flattened box still
 * emits, and an `image_plane_3d` with a `region` emits from the part it shows. Emit points
 * follow the surface where it is at the frame. A surface with no area emits nothing.
 * 
 * Particles are drawn as `instance_3d` copies are, sharing the object's meshes and materials,
 * with its lights and camera left out. They are drawn at once, with no order among them, so the
 * object must be opaque or masked: a blended surface, or one showing a raster such as an image
 * plane, fails the render. Fade particles with `scale_over_life` rather than opacity. A
 * `particles_3d` may sit under an `instance_3d` of `count` 1, which places it as a group would,
 * but more copies of particles, particles of particles, and particles emitted from particles
 * fail the render.
 */
export interface Particles3dNode extends CompositionNodeBase<"particles_3d"> {
  readonly params?: {
    /**
     * Turns each particle so that its +Y follows the normal of the surface where it was emitted.
     * Off, particles keep the node's axes.
     */
    readonly align_to_normal?: ExpressionValue<boolean>;
    /**
     * Particles, from 0 to 100000. Each is one copy of `object`. With `rate` above 0, they are
     * slots that are born one after another and born again once all have been.
     */
    readonly count?: ExpressionValue<number>;
    /**
     * Acceleration in world units per second squared along X, Y and Z, in the node's own space:
     * `[0, -9.8, 0]` makes particles fall. A particle is at `emit + velocity * age + gravity *
     * age² / 2`.
     */
    readonly gravity?: ExpressionValue<Vec3>;
    /**
     * Seconds a particle lives once born, after which it draws nothing until it is born again.
     * 0 lives until it is born again, or forever when `rate` is 0. With `rate` above 0, a
     * particle is born again every `count / rate` seconds, which cuts a longer lifetime short.
     */
    readonly lifetime?: ExpressionValue<number>;
    /** Position in world units along X, Y and Z of the whole system in the parent's space: the surface, the particles and, without a surface, the point they are emitted from move with it. */
    readonly position?: ExpressionValue<Vec3>;
    /**
     * Particles born per second: particle `k` is born `k / rate` seconds into the composition,
     * and born again, somewhere new, every `count / rate` seconds after. 0 gives birth to all of
     * them at once, at 0 seconds, and never again.
     */
    readonly rate?: ExpressionValue<number>;
    /** Rotation in degrees about X, Y and Z of the whole system, applied as yaw about Y, then pitch about the turned X, then roll about the turned Z. It turns `gravity`, and the direction particles are emitted along without a surface, with the rest. */
    readonly rotation?: ExpressionValue<Vec3>;
    /**
     * Most degrees a particle turns about an axis picked at random, by an angle picked at random
     * up to this. 180 turns particles every way.
     */
    readonly rotation_jitter?: ExpressionValue<number>;
    /**
     * The smallest and largest uniform scale of a particle, each picked at random between them.
     * Negative scales are taken as 0.
     */
    readonly scale?: ExpressionValue<Vec2>;
    /**
     * The scale multiplier at a particle's birth and at the end of its `lifetime`, between which
     * it moves in a straight line with its age. Fade particles out with an end of 0. With a
     * `lifetime` of 0 the start applies throughout.
     */
    readonly scale_over_life?: ExpressionValue<Vec2>;
    /**
     * Picks an unrelated scatter: where each particle is emitted, and its direction, size and
     * turn. The same seed gives the same particles at the same time.
     */
    readonly seed?: ExpressionValue<number>;
    /**
     * World units per second a particle moves at, along its emit direction, from where it is
     * emitted.
     */
    readonly speed?: ExpressionValue<number>;
    /**
     * Degrees the emit direction may lean from the surface normal, or from +Y without a surface,
     * at random within a cone: 0 emits along the normal and 180 every way.
     */
    readonly spread?: ExpressionValue<number>;
  };
}

/** Produces a rasterized vector path source. */
export interface PathNode extends CompositionNodeBase<"path"> {
  readonly params?: {
    /** Pivot for scale and rotation, in pixels relative to `position`. */
    readonly anchor?: ExpressionValue<Vec2>;
    /** SVG-style path data. */
    readonly data?: ExpressionValue<string>;
    /** Enables analytic distance-based edge antialiasing. */
    readonly edge_antialias?: ExpressionValue<boolean>;
    /**
     * Width in untransformed pixels over which the fill's edge fades out, centred on the
     * edge. 0 keeps a sharp edge.
     */
    readonly feather?: ExpressionValue<number>;
    /** Enables fill rendering. */
    readonly fill_enabled?: ExpressionValue<boolean>;
    /** Fill paint. Accepts a solid color or gradient. */
    readonly fill_paint?: ExpressionValue<Paint>;
    /**
     * Motion blur shutter angle in degrees, centred on the frame. 0 is off, 180 is the
     * usual film look and 360 smears over the whole frame.
     */
    readonly motion_blur?: ExpressionValue<number>;
    /**
     * Distance in untransformed pixels that the fill grows outward by, or shrinks inward by
     * when negative, rounding the corners it grows around. A shape shrunk past its middle
     * vanishes. The stroke stays on the outline in `data`.
     */
    readonly offset?: ExpressionValue<number>;
    /** Opacity multiplier. */
    readonly opacity?: ExpressionValue<number>;
    /** Path origin in pixels. */
    readonly position?: ExpressionValue<Vec2>;
    /** Copies of the path drawn in one pass. Absent draws the path once. */
    readonly repeat?: Repeat;
    /** Clockwise rotation in degrees, about the anchor. */
    readonly rotation?: ExpressionValue<number>;
    /** Scale multiplier per axis, about the anchor. */
    readonly scale?: ExpressionValue<Vec2>;
    /**
     * Lengths in untransformed pixels that the stroke alternately draws and skips along each
     * contour, starting with a dash. An odd number of lengths is repeated to make the
     * pattern, as in SVG. Each dash has round caps, so a dash of length 0 draws a dot. No
     * lengths, or only zeros, draw a solid stroke. Dashes are measured along the whole
     * contour, and `trim_start` and `trim_end` then clip them.
     */
    readonly stroke_dash?: DashPattern;
    /**
     * Distance in untransformed pixels into the dash pattern at which each contour starts.
     * Increasing it moves the dashes toward the start of the contour.
     */
    readonly stroke_dash_offset?: ExpressionValue<number>;
    /** Enables stroke rendering. */
    readonly stroke_enabled?: ExpressionValue<boolean>;
    /** Stroke paint. Accepts a solid color or gradient. */
    readonly stroke_paint?: ExpressionValue<Paint>;
    /**
     * Stroke width in untransformed pixels. Under non-uniform scale the stroke stretches
     * with the path, so it is wider across the more scaled axis.
     */
    readonly stroke_width?: ExpressionValue<number>;
    /** Normalized end of the visible stroke range for each contour. */
    readonly trim_end?: ExpressionValue<number>;
    /** Normalized start of the visible stroke range for each contour. */
    readonly trim_start?: ExpressionValue<number>;
  };
}

/**
 * The outline of SVG path data, without paint. The fill covers it under the even-odd rule, and
 * a stroke follows its contours, leaving the closing segment of an open contour unstroked.
 * Curves are flattened for the largest scale `render_2d` draws them at.
 */
export interface Path2dNode extends CompositionNodeBase<"path_2d"> {
  readonly params?: {
    /** Pivot for scale and rotation, in pixels relative to `position`. */
    readonly anchor?: ExpressionValue<Vec2>;
    /** SVG-style path data, laid out in untransformed pixels from `position`. */
    readonly data?: ExpressionValue<string>;
    /** Path origin in pixels. */
    readonly position?: ExpressionValue<Vec2>;
    /** Clockwise rotation in degrees, about the anchor. */
    readonly rotation?: ExpressionValue<number>;
    /** Scale multiplier per axis, about the anchor. */
    readonly scale?: ExpressionValue<Vec2>;
  };
}

/** Blurs a raster along circles about a centre, as a spin. */
export interface RadialBlurNode extends CompositionNodeBase<"radial_blur"> {
  readonly params?: {
    /** Arc in degrees each pixel is spread along about `center`, centred on it, up to 360. */
    readonly amount?: ExpressionValue<number>;
    /**
     * Centre of the spin in canvas pixels. The canvas centre, `[width / 2, height / 2]`, when
     * absent.
     */
    readonly center?: ExpressionValue<Vec2>;
    /** What the source reads as beyond the canvas. */
    readonly edge?: ExpressionValue<EdgeMode>;
  };
}

/** Composites a variadic stack of raster layers in order. */
export interface RasterMultimergeNode extends CompositionNodeBase<"raster_multimerge"> {
  readonly params?: {
    /**
     * Blend mode used for each layer in the stack. `normal` composites in linear light; every
     * other mode applies its formula to the sRGB-encoded colours and composites the result in
     * linear light.
     */
    readonly blend_mode?: ExpressionValue<BlendMode>;
    /** Opacity of each layer above the first, which is the base and is used as is. */
    readonly opacity?: ExpressionValue<number>;
  };
}

/**
 * Rasterizes a drawing in one pass over the canvas: each 16 by 16 pixel tile composites the
 * drawables that reach it, in order, with normal blending. Outlines are measured per pixel, so
 * they stay sharp under any transform.
 */
export interface Render2dNode extends CompositionNodeBase<"render_2d"> {
  readonly params?: Readonly<Record<string, never>>;
}

/**
 * Draws a 3D scene into a raster, with a transparent background unless it shows its environment
 * map; or, by `output`, its depth or normals, for 2D effects such as fog.
 */
export interface Render3dNode extends CompositionNodeBase<"render_3d"> {
  readonly params?: {
    /**
     * Distance from the camera, in world units, that `depth` output maps to 1, and past which it
     * stays 1. 0 uses the camera's `far`, which spreads the 0 to 1 range thin over a scene much
     * nearer than it.
     */
    readonly depth_far?: ExpressionValue<number>;
    /**
     * Distance from the camera, in world units, that `depth` output maps to 0. 0 uses the
     * camera's `near`.
     */
    readonly depth_near?: ExpressionValue<number>;
    /**
     * Brightness of the light from all around that surfaces reflect and are lit by: the
     * `environment_map` when one is set, and otherwise a built-in studio of softboxes. 0 turns it
     * off.
     */
    readonly environment?: ExpressionValue<number>;
    /**
     * Shows the environment map behind the scene, through the exposure and tone mapping but not
     * the fog, which makes the output opaque. Shadow catchers darken it.
     */
    readonly environment_background?: ExpressionValue<boolean>;
    /** How blurred the background is, as a surface of this roughness reflects it: 0 is sharp. */
    readonly environment_background_blur?: ExpressionValue<number>;
    /**
     * An equirectangular Radiance `.hdr` or OpenEXR `.exr` file that lights the scene from all
     * around in place of the studio: a path or `media` alias, or `asset:<id>` for an environment
     * map asset of the host's. Its centre is the view along -Z, with +X to its right and +Y at
     * its top, and it is stretched over the whole sphere whatever its aspect. Non-finite and
     * negative pixels are read as black. While a map lights a scene without lights, it gets no
     * default ones. Empty uses the studio.
     */
    readonly environment_map?: ExpressionValue<string>;
    /** Turn of the environment map about +Y in degrees, as a yaw turns an object. */
    readonly environment_rotation?: ExpressionValue<number>;
    /** Exposure adjustment in stops before tone mapping. */
    readonly exposure?: ExpressionValue<number>;
    /** Colour surfaces fade to with distance. Must be a solid color; a gradient fails `check`. */
    readonly fog_color?: ExpressionValue<Color>;
    /**
     * How quickly surfaces fade into the fog: the fraction of their colour left after `d` world
     * units is e^(-density * d). 0 turns fog off.
     */
    readonly fog_density?: ExpressionValue<number>;
    /** Output height in pixels. Use 0 to match the composition height. */
    readonly height?: number;
    /**
     * What the raster holds: the lit scene, its depth or its normals. A composition that needs
     * more than one draws the same scene with a `render_3d` for each.
     */
    readonly output?: Render3dOutput;
    /** Renders this many times wider and taller, then averages down, to antialias edges. */
    readonly supersample?: ExpressionValue<number>;
    /** How light brighter than white is brought into range. */
    readonly tone_mapping?: ToneMapping;
    /** Output width in pixels. Use 0 to match the composition width. */
    readonly width?: number;
  };
}

/** Resamples a raster into a rectangle placed on the composition canvas. */
export interface ResizeNode extends CompositionNodeBase<"resize"> {
  readonly params?: {
    /** Output height in pixels. */
    readonly height?: ExpressionValue<number>;
    /** How the source raster should fit the output bounds. */
    readonly mode?: ResizeMode;
    /** Sampling filter used when resizing. */
    readonly sampling?: ExpressionValue<RasterSampling>;
    /** Output width in pixels. */
    readonly width?: ExpressionValue<number>;
    /** Left edge of the output rectangle in pixels. */
    readonly x?: ExpressionValue<number>;
    /** Top edge of the output rectangle in pixels. */
    readonly y?: ExpressionValue<number>;
  };
}

/** Composites a blurred alpha shadow behind a raster. */
export interface ShadowNode extends CompositionNodeBase<"shadow"> {
  readonly params?: {
    /** Shadow color. Must be a solid color; a gradient is an error. */
    readonly color?: ExpressionValue<Paint>;
    /** Horizontal shadow offset in pixels. */
    readonly offset_x?: ExpressionValue<number>;
    /** Vertical shadow offset in pixels. */
    readonly offset_y?: ExpressionValue<number>;
    /** Shadow opacity. */
    readonly opacity?: ExpressionValue<number>;
    /** Shadow blur radius in pixels. Fractional radii blend smoothly. Radii above about 588 look the same. */
    readonly radius?: ExpressionValue<number>;
  };
}

/**
 * Casts shadows of every drawable in its drawing, all beneath the drawing's own drawables rather
 * than between them. Each shadow's copies of the drawables are drawn in the drawing's order,
 * and the shadows in list order. Shadows of drawables that overlap composite over each other,
 * so where they overlap they are darker than one Gaussian shadow of their union would be. A
 * shadow of a fill follows the filled outline, a shadow of a stroke the stroked band, and a
 * shadow of a shadow combines both: offsets and spreads add up and radii add as Gaussians do.
 * Lengths are in the drawing's pixels, so a `merge_2d` around this node scales them.
 * A shadow is as opaque as the paint it falls from, so a transparent fill casts none.
 */
export interface Shadow2dNode extends CompositionNodeBase<"shadow_2d"> {
  readonly params?: {
    /** Shadows cast beneath the whole drawing, the first lowest. */
    readonly shadows?: Shadows;
  };
}

/** Produces a vector shape layer for GPU rasterization. */
export interface ShapeNode extends CompositionNodeBase<"shape"> {
  readonly params?: {
    /** Pivot for scale and rotation, in pixels relative to `position`. */
    readonly anchor?: ExpressionValue<Vec2>;
    /** Corner radius for rectangle geometry. */
    readonly border_radius?: ExpressionValue<number>;
    /** Enables analytic distance-based edge antialiasing. */
    readonly edge_antialias?: ExpressionValue<boolean>;
    /** Enables fill rendering. */
    readonly fill_enabled?: ExpressionValue<boolean>;
    /** Fill paint. Accepts a solid color or gradient. */
    readonly fill_paint?: ExpressionValue<Paint>;
    /** Geometry primitive to rasterize. */
    readonly geometry_kind?: ShapeGeometryKind;
    /**
     * Shape height in pixels; 0 draws nothing and anything thinner than a pixel draws a pixel
     * tall.
     */
    readonly height?: ExpressionValue<number>;
    /**
     * Motion blur shutter angle in degrees, centred on the frame. 0 is off, 180 is the
     * usual film look and 360 smears over the whole frame.
     */
    readonly motion_blur?: ExpressionValue<number>;
    /** Opacity multiplier. */
    readonly opacity?: ExpressionValue<number>;
    /** Shape origin in pixels. */
    readonly position?: ExpressionValue<Vec2>;
    /** Copies of the shape drawn in one pass. Absent draws the shape once. */
    readonly repeat?: Repeat;
    /** Clockwise rotation in degrees, about the anchor. */
    readonly rotation?: ExpressionValue<number>;
    /** Scale multiplier per axis, about the anchor. */
    readonly scale?: ExpressionValue<Vec2>;
    /** Enables stroke rendering. */
    readonly stroke_enabled?: ExpressionValue<boolean>;
    /** Stroke paint. Accepts a solid color or gradient. */
    readonly stroke_paint?: ExpressionValue<Paint>;
    /**
     * Stroke width in untransformed pixels. Under non-uniform scale the stroke stretches
     * with the shape, so it is wider across the more scaled axis.
     */
    readonly stroke_width?: ExpressionValue<number>;
    /**
     * Shape width in pixels; 0 draws nothing and anything thinner than a pixel draws a pixel
     * wide.
     */
    readonly width?: ExpressionValue<number>;
  };
}

/**
 * The outline of a rectangle or ellipse, without paint, measured analytically. A stroke of a
 * shape is always whole: `stroke_2d`'s trim and dash apply to paths only.
 */
export interface Shape2dNode extends CompositionNodeBase<"shape_2d"> {
  readonly params?: {
    /** Pivot for scale and rotation, in pixels relative to `position`. */
    readonly anchor?: ExpressionValue<Vec2>;
    /** Corner radius for rectangle geometry. */
    readonly border_radius?: ExpressionValue<number>;
    /** Geometry primitive the outline follows. */
    readonly geometry_kind?: ShapeGeometryKind;
    /**
     * Shape height in pixels; 0 draws nothing and anything thinner than a pixel draws a pixel
     * tall.
     */
    readonly height?: ExpressionValue<number>;
    /** Shape origin in pixels: its top left corner. */
    readonly position?: ExpressionValue<Vec2>;
    /** Clockwise rotation in degrees, about the anchor. */
    readonly rotation?: ExpressionValue<number>;
    /** Scale multiplier per axis, about the anchor. */
    readonly scale?: ExpressionValue<Vec2>;
    /**
     * Shape width in pixels; 0 draws nothing and anything thinner than a pixel draws a pixel
     * wide.
     */
    readonly width?: ExpressionValue<number>;
  };
}

/**
 * A primitive solid: box, sphere, plane, cylinder, torus or cone, centred on its position. Lit,
 * single-sided and white unless a `material_3d` is wired into `material`. Its material's
 * `texture` shows upright seen from outside: whole on each face of a box, the top and bottom
 * faces upright to a camera on +Z tilted to look at them, and whole on a plane seen from above,
 * its top edge towards -Z. A sphere, cylinder, cone or torus wraps it around Y, its left edge at
 * -Z and running towards -X, so a camera on +Z sees its middle. A sphere maps it
 * equirectangularly from the top pole to the bottom one, and a cylinder's or cone's side from
 * top to bottom, with the circle inscribed in the texture on each cap, upright as on a box. A
 * torus wraps the texture's height around its tube, from the inner equator over the top, so its
 * middle row runs around the outer equator.
 * 
 * A box takes a material for each face from `top_material`, `bottom_material`, `left_material`,
 * `right_material`, `front_material` and `back_material`, which are its +Y, -Y, -X, +X, +Z and
 * -Z faces in its own axes before `rotation`; the front faces a camera looking down -Z. A face
 * with none wired uses `material`, and each face shows its own material's texture. A face
 * material wired into any other shape fails the render naming the input. The faces draw as one
 * object each, merged where neighbours share a material, from the same mesh, so a box with face
 * materials costs a draw for each run of faces, and under `instance_3d` each draws all its
 * copies.
 */
export interface Shape3dNode extends CompositionNodeBase<"shape_3d"> {
  readonly params?: {
    /** Position in world units along X, Y and Z, in the parent's space. */
    readonly position?: ExpressionValue<Vec3>;
    /**
     * Rotation in degrees about X, Y and Z, applied as yaw about Y, then pitch about the turned
     * X, then roll about the turned Z.
     */
    readonly rotation?: ExpressionValue<Vec3>;
    /** Scale multiplier along X, Y and Z, applied before the rotation. */
    readonly scale?: ExpressionValue<Vec3>;
    /** Primitive to build. */
    readonly shape?: Shape3dKind;
    /** Width, height and depth in world units, along X, Y and Z before the rotation. */
    readonly size?: ExpressionValue<Vec3>;
  };
}

/**
 * Sharpens a raster with an unsharp mask: detail is the difference between a pixel's luminance
 * and that of a blurred copy, and sharpening adds `amount` times it back.
 * 
 * It works on straight colour, with luminance (Rec. 709) on the sRGB-encoded values. The detail
 * is `luminance - blurred luminance`, reduced towards 0 by `threshold`, and the sharpened
 * luminance is `luminance + amount * detail`. That is held between the darkest and brightest
 * luminance in the 3×3 pixels around it, so hard edges get no light or dark halo. The change is
 * added equally to red, green and blue, which keeps the hue and adds no colour fringes; colour
 * brighter than white stays unclipped. Alpha is unchanged and the output covers the source's
 * area. For example, `amount` 1.5 with `radius` 2 and `threshold` 0.02 firms up edges and fine
 * texture while leaving faint grain alone.
 */
export interface SharpenNode extends CompositionNodeBase<"sharpen"> {
  readonly params?: {
    /** Strength of the sharpening. 0 leaves the raster as it is; 1 adds the detail back once. */
    readonly amount?: ExpressionValue<number>;
    /**
     * Blur radius in pixels of the soft copy the detail is measured against, as on `blur`. Small
     * radii sharpen fine texture, large ones broad edges. 0 leaves the raster as it is.
     */
    readonly radius?: ExpressionValue<number>;
    /**
     * The smallest local contrast that is sharpened, from 0 to 1, in sRGB-encoded luminance. Finer
     * detail, such as noise, is left alone, and stronger detail is sharpened by what exceeds it.
     */
    readonly threshold?: ExpressionValue<number>;
  };
}

/**
 * Strokes its geometry's outline with a paint, as a drawing of one drawable. Caps and joins are
 * round. Trim and dash apply to paths; a shape's stroke is always whole.
 */
export interface Stroke2dNode extends CompositionNodeBase<"stroke_2d"> {
  readonly params?: {
    /**
     * Lengths in the geometry's untransformed pixels that the stroke alternately draws and
     * skips along each contour of a path, starting with a dash.
     */
    readonly dash?: DashPattern;
    /**
     * Distance in the geometry's untransformed pixels into the dash pattern at which each
     * contour starts.
     */
    readonly dash_offset?: ExpressionValue<number>;
    /** Opacity multiplier. */
    readonly opacity?: ExpressionValue<number>;
    /**
     * Stroke paint. Accepts a solid color or gradient, laid out in the geometry's untransformed
     * pixels.
     */
    readonly paint?: ExpressionValue<Paint>;
    /** Normalized end of the visible stroke range for each contour of a path. */
    readonly trim_end?: ExpressionValue<number>;
    /** Normalized start of the visible stroke range for each contour of a path. */
    readonly trim_start?: ExpressionValue<number>;
    /**
     * Stroke width in the geometry's untransformed pixels. Under non-uniform scale the stroke
     * stretches with the geometry, so it is wider across the more scaled axis.
     */
    readonly width?: ExpressionValue<number>;
  };
}

/** Selects one raster input according to a controlled layer index. */
export interface SwitchNode extends CompositionNodeBase<"switch"> {
  readonly params?: {
    /** Zero-based input index to route to the output. */
    readonly selected_layer?: ExpressionValue<number>;
  };
}

/** Produces a text source. */
export interface TextNode extends CompositionNodeBase<"text"> {
  readonly params?: {
    /** Horizontal text alignment. */
    readonly alignment_horizontal?: TextAlignmentHorizontal;
    /** Vertical text alignment. */
    readonly alignment_vertical?: TextAlignmentVertical;
    /** Pivot for scale and rotation, in pixels relative to `position`. */
    readonly anchor?: ExpressionValue<Vec2>;
    /** Text color, and that of spans without their own. */
    readonly color?: ExpressionValue<Paint>;
    /**
     * Text to render: a string, or spans that each override the style these params give. A
     * node draws at most 16384 glyphs unless the host sets another limit, counting a stroked
     * glyph twice and each decoration rect once; whitespace is not drawn, and more is a render
     * error.
     */
    readonly content?: ExpressionValue<TextContent>;
    /**
     * Whether the text shrinks to fit `max_width`, `max_lines` and `max_height` without breaking
     * a word, before any lines are dropped. Every font size, letter spacing, `line_height`,
     * baseline shift, paragraph spacing, decoration size and stroke width scales by the largest
     * factor up to 1 that fits.
     */
    readonly fit?: TextFit;
    /** Font family name, or `asset:<id>` for a font asset of the host's. */
    readonly font_family?: ExpressionValue<string>;
    /**
     * OpenType features by four-character tag, such as `{ "tnum": 1, "liga": 0 }`. 0 turns a
     * feature off, 1 turns it on and larger values select an alternate. Values take literals
     * or expressions, but the whole map cannot be an expression.
     */
    readonly font_features?: FontFeatures;
    /** Font size in pixels. */
    readonly font_size?: ExpressionValue<number>;
    /** Font style. */
    readonly font_style?: ExpressionValue<TextFontStyle>;
    /** Font weight. Variable fonts render any value in their weight range. */
    readonly font_weight?: ExpressionValue<number>;
    /**
     * Offset of each glyph in pixels. The `glyph_*` params are evaluated for every glyph,
     * and can read its `glyph`, `word`, `line` and `span` index and their counts.
     */
    readonly glyph_offset?: ExpressionValue<Vec2>;
    /** Opacity multiplier of each glyph, applied before `opacity`. */
    readonly glyph_opacity?: ExpressionValue<number>;
    /** Clockwise rotation of each glyph in degrees, about the middle of its advance and line. */
    readonly glyph_rotation?: ExpressionValue<number>;
    /** Scale multiplier of each glyph per axis, about the middle of its advance and line. */
    readonly glyph_scale?: ExpressionValue<Vec2>;
    /**
     * Box behind each line of the text, and of spans that leave theirs unset. Off when
     * absent.
     */
    readonly highlight?: TextHighlight;
    /** Extra space after every glyph in pixels. Negative values tighten the text. */
    readonly letter_spacing?: ExpressionValue<number>;
    /** Distance between lines in pixels. Use 0 for 1.2 × the font size. */
    readonly line_height?: ExpressionValue<number>;
    /** Most height in pixels of the lines to show. Unlimited when absent. */
    readonly max_height?: ExpressionValue<number>;
    /** Most lines to show. Unlimited when absent. */
    readonly max_lines?: ExpressionValue<number>;
    /** Maximum line width in pixels. Use 0 for automatic width. */
    readonly max_width?: ExpressionValue<number>;
    /**
     * Smallest `font_size` that `fit` shrinks the text to. Lines that still do not fit are
     * dropped by `overflow`.
     */
    readonly min_font_size?: ExpressionValue<number>;
    /**
     * Motion blur shutter angle in degrees, centred on the frame. 0 is off, 180 is the
     * usual film look and 360 smears over the whole frame. Blurs the text's own movement,
     * not that of the `glyph_*` params.
     */
    readonly motion_blur?: ExpressionValue<number>;
    /** Opacity multiplier. */
    readonly opacity?: ExpressionValue<number>;
    /**
     * How the last line shown ends when lines past `max_lines` or `max_height` are dropped: as
     * it is, or in an ellipsis. Clusters at that line's end are dropped until the ellipsis fits
     * `max_width`. The ellipsis takes the style and paint of the text it follows, and is one
     * glyph, numbered after the last one shown.
     */
    readonly overflow?: TextOverflow;
    /**
     * Box a span's own gradient `color` spans: the span's lines, or the whole text. The
     * node's `color` always spans the whole text.
     */
    readonly paint_space?: TextPaintSpace;
    /** Enables 4×4 supersampling when evaluating paint at each glyph pixel. */
    readonly paint_supersample?: ExpressionValue<boolean>;
    /**
     * Extra space in pixels after each paragraph, but the last. A line break starts a new
     * paragraph.
     */
    readonly paragraph_spacing?: ExpressionValue<number>;
    /** Text origin in pixels. */
    readonly position?: ExpressionValue<Vec2>;
    /** Glyph rendering mode. MSDF reuses outline distance fields across sizes; Auto is MSDF from 512 px. */
    readonly render_mode?: TextRenderMode;
    /** Clockwise rotation in degrees, about the anchor. */
    readonly rotation?: ExpressionValue<number>;
    /**
     * Scale multiplier per axis, about the anchor. Raster glyphs are resampled, so
     * use MSDF rendering to keep scaled text sharp.
     */
    readonly scale?: ExpressionValue<Vec2>;
    /** Line through the text, and through spans that leave theirs unset. Off when absent. */
    readonly strikethrough?: TextLine;
    /**
     * Outline along the glyphs, and along those of spans that leave theirs unset. Off when
     * absent. It does not change the layout or the measured size. `glyph_opacity` fades a
     * glyph's stroke and fill as one.
     */
    readonly stroke?: TextStroke;
    /** Case applied to the text, and to spans that leave theirs unset. */
    readonly text_transform?: ExpressionValue<TextTransform>;
    /**
     * Line under the text, and under spans that leave theirs unset. Off when absent. Its
     * fields take literals or expressions, but the whole line cannot be an expression.
     */
    readonly underline?: TextLine;
  };
}

/**
 * The outlines of text's glyphs, without paint, so fills, strokes, offsets and shadows style
 * type as they do any other geometry, and one `text_2d` can feed several of them:
 * 
 * ```json
 * { "id": 1, "type": "text_2d", "params": { "content": "Lumen", "font_size": 240, "position": [960, 540], "alignment_horizontal": "center", "alignment_vertical": "middle" } },
 * { "id": 2, "type": "offset_2d", "params": { "offset": 12 }, "in": { "geometry": 1 } },
 * { "id": 3, "type": "fill_2d", "params": { "paint": "#ee5b24" }, "in": { "geometry": 2 } },
 * { "id": 4, "type": "fill_2d", "params": { "paint": "#ffffff" }, "in": { "geometry": 1 } },
 * { "id": 5, "type": "stroke_2d", "params": { "paint": "#111111", "width": 4 }, "in": { "geometry": 1 } },
 * { "id": 6, "type": "merge_2d", "in": { "drawings": [3, 4, 5] } },
 * { "id": 7, "type": "render_2d", "in": { "drawing": 6 } }
 * ```
 * 
 * The text is shaped as a `text` node with the same font, size and layout shapes it, with its
 * kerning, ligatures, font fallback and wrapping, so with left and top alignment a white fill
 * lines up with a white `text` node at the same `position`. The outline covers what the glyphs
 * cover by the nonzero rule, as fonts expect, so contours that overlap, as in variable fonts,
 * and glyphs that overlap each other fill as one, and a stroke follows only the outline's
 * edge, measuring trim and dash along each of its contours. Glyphs are shaped and outlined
 * again only when the text, font or layout change, not when the transform or the styles
 * animate. Text of more than 8192 outline points is drawn as several outlines one after
 * another, glyph by glyph, which shadows and translucent paints treat as separate drawables
 * where they overlap. Curves are flattened for the largest scale `render_2d` draws them at,
 * coarser where a text would pass 1048576 points.
 * 
 * It suits titles and short lines. A moving paragraph costs far more than a `text` node, whose
 * glyphs are drawn from cached images, since its outline is placed again every frame. One
 * style covers the whole text: rich text spans, decorations and the `glyph_*` params of a
 * `text` node have no counterpart.
 */
export interface Text2dNode extends CompositionNodeBase<"text_2d"> {
  readonly params?: {
    /**
     * How lines align with each other, and which point of the text's box sits at `position`:
     * its left edge, centre or right edge. Justified lines anchor at the left edge.
     */
    readonly alignment_horizontal?: TextAlignmentHorizontal;
    /**
     * Which point of the text's box sits at `position` vertically: the top of its first line,
     * its middle, or the bottom of its last line.
     */
    readonly alignment_vertical?: TextAlignmentVertical;
    /** Pivot for scale and rotation, in pixels relative to `position`. */
    readonly anchor?: ExpressionValue<Vec2>;
    /**
     * Text to outline, in one style. Line breaks start new lines. Whitespace has no outline, and
     * glyphs that their font draws from colour or bitmap tables, such as emoji, have none either
     * and are left out with a `font.no_outlines` warning. A node outlines at most as many glyphs
     * as the host's text glyph limit lets a `text` node draw, 16384 unless the host sets
     * another, and one glyph's outline has at most 4096 commands; more is a render error.
     */
    readonly content?: ExpressionValue<string>;
    /**
     * Font family name, or `asset:<id>` for a font asset of the host's. A family no font answers
     * to falls back as a `text` node's does.
     */
    readonly font_family?: ExpressionValue<string>;
    /**
     * OpenType features by four-character tag, such as `{ "tnum": 1, "liga": 0 }`. 0 turns a
     * feature off, 1 turns it on and larger values select an alternate. Values take literals
     * or expressions, but the whole map cannot be an expression.
     */
    readonly font_features?: FontFeatures;
    /**
     * Font size in pixels: the height of the font's em square. 0 draws nothing, and so does
     * anything under 0.000001. At most 1000000, as are `max_width`, `letter_spacing` and
     * `line_height`.
     */
    readonly font_size?: ExpressionValue<number>;
    /** Font style. */
    readonly font_style?: ExpressionValue<TextFontStyle>;
    /** Font weight. Variable fonts render any value in their weight range. */
    readonly font_weight?: ExpressionValue<number>;
    /** Extra space after every glyph in pixels. Negative values tighten the text. */
    readonly letter_spacing?: ExpressionValue<number>;
    /** Distance between lines in pixels. Use 0 for 1.2 × the font size. */
    readonly line_height?: ExpressionValue<number>;
    /** Maximum line width in pixels, at which lines wrap. Use 0 for automatic width. */
    readonly max_width?: ExpressionValue<number>;
    /** Where the point of the text's box that the alignments pick sits, in pixels. */
    readonly position?: ExpressionValue<Vec2>;
    /** Clockwise rotation in degrees, about the anchor. */
    readonly rotation?: ExpressionValue<number>;
    /** Scale multiplier per axis, about the anchor. */
    readonly scale?: ExpressionValue<Vec2>;
    /** Case applied to the text. */
    readonly text_transform?: ExpressionValue<TextTransform>;
  };
}

/**
 * Text from its font's outlines, extruded into a solid, lit, single-sided and white unless
 * a `material_3d` is wired into `material`. A `material_3d` wired into `side_material` covers the
 * side walls and the bevel instead, leaving the front and back faces to `material`. The text is
 * shaped as a `text` node with the same font, size and layout shapes it, with its kerning, ligatures, font fallback and wrapping, and lies in the XY plane facing
 * +Z, reading along +X, with `alignment_horizontal` and `alignment_vertical` choosing the
 * point of its box at `position`. Its geometry is built again only when the text, font, layout or
 * bevel change, or its size or depth do with a bevel, so animating its transform or material
 * costs no more than for a `shape_3d`. One style covers the whole text: rich text spans, decorations, strokes and the
 * `glyph_*` params of a `text` node have no counterpart.
 */
export interface Text3dNode extends CompositionNodeBase<"text_3d"> {
  readonly params?: {
    /**
     * How lines align with each other, and which point of the text's box sits at `position`:
     * its left edge, centre or right edge. Justified lines anchor at the left edge.
     */
    readonly alignment_horizontal?: TextAlignmentHorizontal;
    /**
     * Which point of the text's box sits at `position` vertically: the top of its first line,
     * its middle, or the bottom of its last line.
     */
    readonly alignment_vertical?: TextAlignmentVertical;
    /**
     * Steps of the bevel's quarter-round profile, up to 16: 1 is a flat 45° chamfer, and 0 is no
     * bevel.
     */
    readonly bevel_segments?: ExpressionValue<number>;
    /**
     * How far the bevel rounds off each glyph's edges in world units, in from the outline and in
     * from the front and back, up to half of `depth`; 0 is none. The outline keeps its size
     * where the sides meet the bevel. A glyph whose strokes are too thin for the bevel gets the
     * widest one that fits it, so at regular weights bevels past about 0.04 of the font size
     * stop growing on most glyphs.
     */
    readonly bevel_size?: ExpressionValue<number>;
    /**
     * Text to extrude, in one style. Line breaks start new lines. Whitespace is not drawn, and
     * glyphs that their font draws from colour or bitmap tables, such as emoji, have no outline
     * and are left out with a `font.no_outlines` warning. A node extrudes at most as many glyphs
     * as the host's text glyph limit lets a `text` node draw, 16384 unless the host sets
     * another, and at most 4000000 vertices and 12000000 indices; more is a render error. One
     * glyph builds from an outline of at most 4096 commands, 64 contours and 8192 flattened
     * points, and takes at most 262144 vertices and 786432 indices, and 3072 points where it is
     * bevelled; a font with a glyph past any of these fails the render rather than the glyph
     * being left out.
     */
    readonly content?: ExpressionValue<string>;
    /**
     * Thickness along Z in world units, centred on `position`, so the front faces +Z at half of
     * it. 0 is flat.
     */
    readonly depth?: ExpressionValue<number>;
    /**
     * Font family name, or `asset:<id>` for a font asset of the host's. A family no font answers
     * to falls back as a `text` node's does.
     */
    readonly font_family?: ExpressionValue<string>;
    /**
     * OpenType features by four-character tag, such as `{ "tnum": 1, "liga": 0 }`. 0 turns a
     * feature off, 1 turns it on and larger values select an alternate. Values take literals
     * or expressions, but the whole map cannot be an expression.
     */
    readonly font_features?: FontFeatures;
    /**
     * Font size in world units: the height of the font's em square, so capitals are about 0.7
     * of it tall. At 1, the default, a word is about as tall as a default `shape_3d` box is
     * wide. 0 draws nothing, and so does anything under 0.000001. At most 1000000; `depth`,
     * `bevel_size`, `max_width`, `letter_spacing` and `line_height` may be at most 100000 times
     * it, and at most 1000000 themselves.
     */
    readonly font_size?: ExpressionValue<number>;
    /** Font style. */
    readonly font_style?: ExpressionValue<TextFontStyle>;
    /** Font weight. Variable fonts render any value in their weight range. */
    readonly font_weight?: ExpressionValue<number>;
    /** Extra space after every glyph in world units. Negative values tighten the text. */
    readonly letter_spacing?: ExpressionValue<number>;
    /** Distance between lines in world units. Use 0 for 1.2 × the font size. */
    readonly line_height?: ExpressionValue<number>;
    /** Maximum line width in world units, at which lines wrap. Use 0 for automatic width. */
    readonly max_width?: ExpressionValue<number>;
    /** Position in world units along X, Y and Z, in the parent's space. */
    readonly position?: ExpressionValue<Vec3>;
    /**
     * Rotation in degrees about X, Y and Z, applied as yaw about Y, then pitch about the turned
     * X, then roll about the turned Z.
     */
    readonly rotation?: ExpressionValue<Vec3>;
    /** Scale multiplier along X, Y and Z, applied before the rotation. */
    readonly scale?: ExpressionValue<Vec3>;
    /** Case applied to the text. */
    readonly text_transform?: ExpressionValue<TextTransform>;
  };
}

/** Evaluates a raster input at another frame. */
export interface TimeRemapNode extends CompositionNodeBase<"time_remap"> {
  readonly params?: {
    /** Source frame to sample. */
    readonly frame?: ExpressionValue<number>;
    /** Enables looping between the configured loop bounds. */
    readonly loop_enabled?: ExpressionValue<boolean>;
    /** Last frame in the loop range. */
    readonly loop_end?: ExpressionValue<number>;
    /** First frame in the loop range. */
    readonly loop_start?: ExpressionValue<number>;
  };
}

/** Transforms a raster into the composition canvas bounds. */
export interface TransformNode extends CompositionNodeBase<"transform"> {
  readonly params?: {
    /** Uses the pivot as given; when off, the pivot is the source centre. */
    readonly custom_pivot?: ExpressionValue<boolean>;
    /**
     * Motion blur shutter angle in degrees, centred on the frame. 0 is off, 180 is the
     * usual film look and 360 smears over the whole frame.
     */
    readonly motion_blur?: ExpressionValue<number>;
    /** Horizontal pivot point in pixels. */
    readonly pivot_x?: ExpressionValue<number>;
    /** Vertical pivot point in pixels. */
    readonly pivot_y?: ExpressionValue<number>;
    /** Rotation in degrees. */
    readonly rotate?: ExpressionValue<number>;
    /** Sampling filter used when transforming. */
    readonly sampling?: ExpressionValue<RasterSampling>;
    /** Horizontal scale multiplier. */
    readonly scale_x?: ExpressionValue<number>;
    /** Vertical scale multiplier. */
    readonly scale_y?: ExpressionValue<number>;
    /** Horizontal translation in pixels. */
    readonly translate_x?: ExpressionValue<number>;
    /** Vertical translation in pixels. */
    readonly translate_y?: ExpressionValue<number>;
  };
}

/** Runs a custom WGSL compute shader over one or more rasters. */
export interface WgslShaderNode extends CompositionNodeBase<"wgsl_shader"> {
  readonly params?: {
    /**
     * WGSL compute shader, or `shader:<name>` for the composition's `shaders` entry of that name;
     * the prelude provides inputs, `input_sampler`, `output` and `lumen`, which holds
     * `resolution`, `render_scale`, `time`, `frame`, and from the `camera` input `view`,
     * `projection` and `camera_position`.
     */
    readonly shader?: ExpressionValue<string>;
    /** Uniform struct field values by name; unset fields are zero. */
    readonly uniforms?: ShaderUniforms;
  };
}

/** Blurs a raster along rays from a centre, as a zoom. */
export interface ZoomBlurNode extends CompositionNodeBase<"zoom_blur"> {
  readonly params?: {
    /**
     * Length of the streak through each pixel, as a fraction of its distance from `center`.
     * The streak runs both ways along the ray, sampled in equal ratios of scale, so it reaches
     * farther away from `center` than towards it.
     */
    readonly amount?: ExpressionValue<number>;
    /**
     * Centre of the zoom in canvas pixels. The canvas centre, `[width / 2, height / 2]`, when
     * absent.
     */
    readonly center?: ExpressionValue<Vec2>;
    /** What the source reads as beyond the canvas. */
    readonly edge?: ExpressionValue<EdgeMode>;
  };
}

